export const atlasExtensionLessons: Lesson[] = [
  {
    id: "direito-11", title: "Direitos fundamentais e sua proteção", duration: 50,
    objective: "Compreender a função dos direitos fundamentais, suas dimensões, limites e mecanismos institucionais de proteção.",
    sections: [
      { heading: "1. Direitos fundamentais e Constituição", paragraphs: ["Direitos fundamentais são posições jurídicas reconhecidas pela Constituição para proteger a dignidade, a liberdade, a igualdade e condições essenciais de participação na vida social. No Brasil, estão distribuídos especialmente no Título II da Constituição de 1988, mas também aparecem em outros dispositivos e em tratados incorporados ao ordenamento.", "Eles não são apenas declarações abstratas. Podem impor deveres de respeito ao Estado, deveres de proteção e, em determinadas situações, orientar relações entre particulares. A extensão desses efeitos depende do direito envolvido, do contexto e da interpretação constitucional." ] },
      { heading: "2. Dimensões e colisões", paragraphs: ["Uma classificação didática distingue direitos civis e políticos, direitos sociais, econômicos e culturais e direitos coletivos ou difusos. Essa divisão ajuda a estudar a história e as funções dos direitos, mas não significa que existam compartimentos isolados: liberdade de expressão, educação, saúde, meio ambiente e participação política podem depender uns dos outros.", "Direitos podem entrar em tensão em casos concretos. A solução exige identificar o âmbito de proteção de cada direito, os fatos relevantes, a base legal da restrição e a justificativa apresentada. A proporcionalidade é uma técnica argumentativa usada em certos contextos para examinar adequação, necessidade e equilíbrio da medida; não é uma fórmula automática que dispense fundamentação." ] },
      { heading: "3. Garantias e instituições", paragraphs: ["A Constituição prevê instrumentos judiciais e institucionais de proteção, como habeas corpus, mandado de segurança, habeas data, mandado de injunção e ação popular, cada qual com pressupostos próprios. Ministério Público, Defensoria Pública, Judiciário, órgãos administrativos e sociedade civil também desempenham funções distintas na proteção de direitos.", "Conhecer o nome de um instrumento não basta. É preciso saber qual direito se busca proteger, quem pode utilizá-lo, contra qual ato ou omissão, em que prazo e perante qual autoridade. Em situações reais, a escolha depende da análise dos fatos e da legislação atualizada." ] }
    ],
    keyTerms: [{term:"Direitos fundamentais",definition:"Direitos reconhecidos constitucionalmente para proteger bens e posições essenciais da pessoa e da coletividade."},{term:"Eficácia",definition:"Modo e intensidade com que uma norma produz efeitos jurídicos."},{term:"Proporcionalidade",definition:"Estrutura de análise de medidas restritivas, com exame de adequação, necessidade e proporcionalidade em sentido estrito."}],
    caseStudy: "Uma prefeitura restringe manifestações em uma praça alegando necessidade de organizar o trânsito. A análise deve considerar liberdade de reunião, segurança, conteúdo e alcance da restrição, existência de alternativas menos gravosas, igualdade de tratamento e base normativa. Não basta afirmar que a medida é boa ou ruim: é necessário justificar sua compatibilidade constitucional.",
    question: {prompt:"Qual afirmação descreve melhor a análise de uma restrição a direito fundamental?", options:["Basta que a autoridade considere a medida conveniente.","Todo direito fundamental é absoluto e nunca admite limitações.","É necessário identificar o direito, a base jurídica, os fatos e justificar a medida à luz da Constituição.","A existência de uma lei elimina qualquer necessidade de controle."], correct:2, explanation:"A análise constitucional exige fundamentação, consideração dos fatos, da base jurídica e dos limites impostos pelos direitos e garantias."},
    reflection: "Escolha uma notícia sobre liberdade de expressão, reunião, privacidade ou igualdade. Separe o direito envolvido, a justificativa da restrição e as informações que ainda precisariam ser verificadas.",
    references: ["BRASIL. Constituição Federal de 1988, especialmente arts. 5º a 17.","BRASIL. Supremo Tribunal Federal — Constituição e jurisprudência: https://portal.stf.jus.br/.","SARLET, Ingo Wolfgang. A eficácia dos direitos fundamentais. Livraria do Advogado."]
  },
  {
    id: "direito-12", title: "Direito imobiliário: propriedade, posse e registro", duration: 55,
    objective: "Distinguir posse, propriedade e registro imobiliário e reconhecer etapas básicas de uma análise documental de imóvel.",
    sections: [
      {heading:"1. Posse não é o mesmo que propriedade",paragraphs:["A posse é uma situação de exercício de poderes de fato sobre um bem, nos termos definidos pelo Código Civil. A propriedade é um direito real que confere ao titular faculdades juridicamente reconhecidas, como usar, gozar, dispor e reivindicar o bem, respeitados os limites legais.","Uma pessoa pode exercer a posse sem ser proprietária; por exemplo, um locatário utiliza o imóvel com base em contrato, mas não se torna dono por isso. Também pode haver situações em que o proprietário não exerce diretamente a posse. A análise exige identificar a origem da ocupação e os documentos correspondentes."]},
      {heading:"2. Matrícula e registro",paragraphs:["A matrícula individualiza juridicamente o imóvel no Registro de Imóveis e reúne atos relevantes relativos à sua situação jurídica. A leitura deve observar descrição, titularidade, registros, averbações, ônus, restrições e continuidade dos atos. Certidões e consultas precisam ser atuais e emitidas pelo serviço competente.","Contratos particulares, recibos, cadastro municipal e pagamento de tributos podem ser relevantes, mas não substituem automaticamente o registro exigido para a aquisição ou constituição de direitos reais. A regra geral do Código Civil para transmissão da propriedade imobiliária entre vivos envolve o registro do título translativo no Registro de Imóveis, observadas as exceções legais."]},
      {heading:"3. Diligência e risco",paragraphs:["Uma análise preliminar deve conferir identidade e poderes dos vendedores, matrícula atualizada, cadeia de titularidade, certidões pertinentes, situação fiscal, ocupação, condomínio, licenças e eventuais restrições urbanísticas ou ambientais. A lista exata depende do tipo de negócio e do imóvel.","A diligência não elimina todo risco. Ela organiza informações, identifica inconsistências e permite decidir se é necessário solicitar documentos adicionais ou orientação jurídica especializada. Nunca se deve prometer regularidade apenas porque um documento isolado foi apresentado."]}
    ],
    keyTerms:[{term:"Posse",definition:"Exercício de fato, pleno ou não, de algum dos poderes inerentes à propriedade, conforme o Código Civil."},{term:"Propriedade",definition:"Direito real que atribui faculdades de usar, gozar, dispor e reivindicar, sujeito a limites legais."},{term:"Matrícula",definition:"Registro que individualiza o imóvel e concentra os atos registrais a ele vinculados."},{term:"Averbação",definition:"Anotação registral de fatos ou alterações juridicamente relevantes, conforme a lei."}],
    caseStudy:"Uma pessoa anuncia um terreno e apresenta apenas contrato particular antigo e carnês de IPTU. Antes de qualquer conclusão, é necessário solicitar a matrícula atualizada, verificar quem figura como titular, confrontar a descrição física, investigar ônus e conferir se o vendedor tem poderes para negociar. O pagamento de IPTU, isoladamente, não prova propriedade.",
    question:{prompt:"Qual documento é central para verificar a situação registral atual de um imóvel?",options:["Uma conta recente de energia.","A matrícula atualizada emitida pelo Registro de Imóveis competente.","Um anúncio publicado em portal imobiliário.","Um comprovante isolado de pagamento de IPTU."],correct:1,explanation:"A matrícula atualizada permite examinar titularidade e atos registrais. Outros documentos podem complementar a diligência, mas não substituem essa consulta."},
    reflection:"Monte um checklist de cinco verificações que faria antes de intermediar uma negociação imobiliária. Explique qual risco cada documento ou consulta ajuda a identificar.",
    references:["BRASIL. Código Civil, arts. 1.196 e seguintes e art. 1.245.","BRASIL. Lei nº 6.015/1973 — Lei de Registros Públicos.","Conselho Nacional de Justiça — Justiça Aberta: https://www.cnj.jus.br/."]
  },
  {
    id:"eco-10", title:"Sistema Financeiro Nacional e papel do Banco Central", duration:50,
    objective:"Mapear os principais participantes do Sistema Financeiro Nacional e explicar funções de regulação, supervisão e política monetária.",
    sections:[
      {heading:"1. Estrutura institucional",paragraphs:["O Sistema Financeiro Nacional reúne órgãos normativos, entidades supervisoras e instituições que operam nos mercados financeiros. Em linhas gerais, o Conselho Monetário Nacional formula diretrizes gerais; o Banco Central do Brasil executa atribuições de política monetária e supervisiona instituições sob sua competência; a CVM regula e fiscaliza o mercado de valores mobiliários.","Bancos, cooperativas de crédito, instituições de pagamento, corretoras, distribuidoras, seguradoras e entidades de previdência atuam em segmentos diferentes e estão sujeitos a regras próprias. Nem toda empresa que oferece serviços financeiros possui a mesma autorização ou proteção regulatória."]},
      {heading:"2. Moeda, crédito e estabilidade",paragraphs:["O Banco Central atua para assegurar a estabilidade de preços e contribuir para a estabilidade e eficiência do sistema financeiro, dentro de seu mandato legal. A política monetária influencia condições de liquidez e custo do crédito, mas seus efeitos sobre inflação, atividade e emprego ocorrem com defasagens e dependem de diversos fatores.","A taxa Selic é a taxa básica de juros da economia e uma referência importante para o custo do dinheiro. Alterações na Selic tendem a influenciar taxas de mercado, mas não determinam de forma idêntica o juro cobrado de cada pessoa: risco, prazo, garantias, custos e concorrência também importam."]},
      {heading:"3. Como verificar uma instituição",paragraphs:["Antes de contratar um serviço financeiro, é prudente verificar a instituição e sua autorização nos canais oficiais, compreender tarifas, riscos, regras de resgate, cobertura aplicável e mecanismos de reclamação. A existência de aplicativo ou publicidade não prova autorização regulatória.","O Fundo Garantidor de Créditos oferece garantia para determinados produtos e instituições, dentro de limites e condições específicas. Não se deve generalizar a cobertura para qualquer investimento ou ativo: ações, fundos e títulos privados possuem riscos e regimes diferentes."]}
    ],
    keyTerms:[{term:"CMN",definition:"Órgão normativo superior do Sistema Financeiro Nacional, responsável por diretrizes gerais da política monetária e creditícia."},{term:"Banco Central",definition:"Autarquia federal que executa atribuições de política monetária, supervisão e estabilidade do sistema financeiro."},{term:"CVM",definition:"Autarquia que regula, desenvolve e fiscaliza o mercado de valores mobiliários."}],
    caseStudy:"Uma plataforma oferece rendimento muito acima da média e afirma ser 'banco autorizado'. Antes de transferir recursos, verifique a razão social, CNPJ, autorização nos registros do Banco Central, natureza jurídica do produto, riscos, liquidez e se há cobertura do FGC. Desconfie de promessas de retorno garantido sem risco.",
    question:{prompt:"Qual é a principal função da CVM?",options:["Definir a taxa Selic em cada reunião.","Regular e fiscalizar o mercado de valores mobiliários.","Garantir qualquer investimento feito por pessoa física.","Emitir todos os cartões de crédito do país."],correct:1,explanation:"A CVM supervisiona o mercado de valores mobiliários; política monetária e supervisão bancária são atribuições distintas."},
    reflection:"Pesquise uma instituição financeira que você conhece. Identifique seu tipo, órgão supervisor e quais riscos existem no produto que ela oferece.",
    references:["Banco Central do Brasil — Sistema Financeiro Nacional: https://www.bcb.gov.br/estabilidadefinanceira/sfn.","Comissão de Valores Mobiliários: https://www.gov.br/cvm/pt-br.","BRASIL. Lei nº 6.038/1974 e Lei nº 6.385/1976."]
  },
  {
    id:"eco-11", title:"Renda fixa: títulos, riscos e rentabilidade real", duration:55,
    objective:"Comparar títulos de renda fixa considerando indexador, prazo, liquidez, tributação, risco de crédito e inflação.",
    sections:[
      {heading:"1. O que significa renda fixa",paragraphs:["Renda fixa é uma categoria em que as regras de remuneração são definidas por contrato ou regulamento. Isso não significa retorno conhecido em qualquer momento nem ausência de risco. O resultado pode depender de taxa prefixada, índice de preços, taxa flutuante, prazo e condições de resgate.","Títulos públicos federais representam dívida do governo federal. CDBs são emitidos por bancos; debêntures são títulos de dívida de empresas; letras de crédito possuem regras específicas. Cada instrumento tem emissor, risco, liquidez e regime tributário próprios."]},
      {heading:"2. Indexadores e marcação a mercado",paragraphs:["Um título prefixado estabelece uma taxa nominal contratada até o vencimento, mas seu preço pode oscilar antes disso. Um título pós-fixado acompanha um indicador, como a taxa DI ou Selic, conforme as regras do produto. Um título indexado à inflação combina uma parcela real com a variação de um índice de preços.","Marcação a mercado significa atualizar o preço do título conforme as condições atuais de negociação. Em títulos prefixados e indexados à inflação, a alta das taxas de mercado costuma reduzir o preço de negociação antes do vencimento; a queda tende a elevá-lo. Se o investidor mantém o título até o vencimento e o emissor paga, as regras contratadas determinam o fluxo, mas vender antes pode gerar ganho ou perda."]},
      {heading:"3. Comparação responsável",paragraphs:["Compare rentabilidade líquida, prazo, possibilidade de resgate, risco do emissor, garantias, impostos, taxas e objetivo financeiro. O FGC cobre determinados depósitos e créditos elegíveis dentro de limites e condições; não cobre todos os títulos nem elimina riscos operacionais ou de liquidez.","A rentabilidade real pode ser estimada por (1 + taxa nominal)/(1 + inflação) − 1. A conta ajuda a evitar confundir aumento do saldo em reais com aumento do poder de compra. Simulações são cenários, não promessa de retorno futuro."]}
    ],
    keyTerms:[{term:"Prefixado",definition:"Remuneração nominal definida no momento da contratação, sujeita à oscilação de preço antes do vencimento."},{term:"Pós-fixado",definition:"Remuneração vinculada a um indicador que varia ao longo do tempo."},{term:"Marcação a mercado",definition:"Atualização do preço de um ativo segundo condições de negociação atuais."},{term:"Risco de crédito",definition:"Possibilidade de o emissor não cumprir pagamentos devidos."}],
    caseStudy:"Duas aplicações oferecem taxas diferentes: uma paga percentual do CDI com liquidez diária; outra oferece taxa prefixada maior, mas vence em três anos. A comparação depende de quando o dinheiro poderá ser necessário, da expectativa de juros, do risco do emissor, dos impostos e da possibilidade de resgate antecipado.",
    question:{prompt:"Por que um título prefixado pode apresentar perda se vendido antes do vencimento?",options:["Porque o preço de mercado pode cair quando as taxas exigidas pelo mercado sobem.","Porque todo título prefixado perde automaticamente 100% do valor.","Porque a inflação deixa de existir no vencimento.","Porque a taxa contratada muda diariamente por decisão do investidor."],correct:0,explanation:"O preço de mercado se ajusta às taxas vigentes. Se as taxas sobem, o preço de títulos antigos com remuneração menor tende a cair."},
    reflection:"Escolha um objetivo financeiro de curto, médio ou longo prazo. Quais características de prazo, liquidez e risco deveriam orientar a escolha de um título? Não indique um produto sem antes definir o objetivo.",
    references:["Tesouro Direto — títulos e funcionamento: https://www.tesourodireto.com.br/.","Banco Central do Brasil — Cidadania Financeira: https://www.bcb.gov.br/cidadaniafinanceira.","CVM — Portal do Investidor: https://www.gov.br/investidor/pt-br."]
  },
  {
    id:"tec-10", title:"Redes de computadores: IP, DNS e HTTPS", duration:55,
    objective:"Explicar como dispositivos se comunicam em redes e qual o papel de endereços IP, DNS, roteamento e HTTPS.",
    sections:[
      {heading:"1. Como os dados atravessam uma rede",paragraphs:["Uma rede conecta dispositivos para trocar dados usando regras e protocolos. Em redes IP, os dados são organizados em pacotes que carregam informações de origem e destino. Roteadores encaminham pacotes entre redes, escolhendo caminhos conforme tabelas e protocolos de roteamento.","Endereço IP identifica uma interface em uma rede lógica. IPv4 usa endereços de 32 bits; IPv6 amplia o espaço de endereçamento para 128 bits. Um endereço pode ser público ou privado, estático ou dinâmico, e não deve ser confundido automaticamente com a identidade de uma pessoa."]},
      {heading:"2. DNS e nomes de domínio",paragraphs:["O DNS traduz nomes legíveis, como exemplo.com, em registros usados para localizar serviços. A resolução pode envolver cache, resolvedores recursivos e servidores autoritativos. Uma resposta DNS não garante que o site seja legítimo: atacantes podem registrar domínios parecidos ou comprometer infraestrutura.","Ao acessar um site, o navegador normalmente consulta DNS, estabelece uma conexão de transporte e, quando usa HTTPS, negocia uma sessão protegida por TLS. Os detalhes variam conforme HTTP/1.1, HTTP/2, HTTP/3 e a infraestrutura utilizada."]},
      {heading:"3. HTTPS e limites de segurança",paragraphs:["HTTPS protege a comunicação entre cliente e servidor por meio de TLS, oferecendo criptografia, integridade e autenticação do servidor por certificados. Isso reduz riscos de interceptação e alteração do tráfego, mas não prova que o conteúdo do site seja verdadeiro ou que a empresa seja confiável.","Segurança depende também de atualizações, autenticação, proteção de contas, validação de entradas, configuração do servidor e comportamento do usuário. Um cadeado no navegador indica uma conexão criptografada com o domínio apresentado, não uma certificação moral ou comercial da página."]}
    ],
    keyTerms:[{term:"IP",definition:"Protocolo de endereçamento e encaminhamento de pacotes entre redes."},{term:"DNS",definition:"Sistema distribuído que associa nomes de domínio a registros de recursos, incluindo endereços."},{term:"Roteador",definition:"Dispositivo que encaminha pacotes entre redes com base em informações de roteamento."},{term:"TLS",definition:"Protocolo criptográfico que protege a comunicação e autentica o servidor em conexões HTTPS."}],
    caseStudy:"Você recebe um link de entrega que imita o domínio de uma transportadora. O site usa HTTPS, mas solicita senha bancária e código de autenticação. O cadeado não comprova legitimidade. Verifique o domínio por um canal independente, não forneça credenciais e reporte a tentativa.",
    question:{prompt:"O que HTTPS oferece principalmente?",options:["Garantia de que todo conteúdo do site é verdadeiro.","Criptografia e integridade da comunicação, além de autenticação do servidor.","Proteção contra qualquer tipo de malware no dispositivo.","Garantia de que a empresa é fiscalizada pelo governo."],correct:1,explanation:"HTTPS protege a conexão, mas não certifica a honestidade do site nem elimina malware ou engenharia social."},
    reflection:"Descreva o caminho simplificado entre digitar um endereço no navegador e carregar uma página. Em quais etapas podem ocorrer falhas ou ataques?",
    references:["MDN Web Docs — HTTP overview: https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Overview.","Cloudflare Learning Center — What is DNS?: https://www.cloudflare.com/learning/dns/what-is-dns/.","OWASP — Transport Layer Security Cheat Sheet: https://cheatsheetseries.owasp.org/."]
  },
  {
    id:"tec-11", title:"Segurança da informação e modelo de ameaças", duration:55,
    objective:"Aplicar os princípios de confidencialidade, integridade e disponibilidade e construir uma análise inicial de ameaças.",
    sections:[
      {heading:"1. A tríade CIA",paragraphs:["Confidencialidade significa que informações só são acessadas por pessoas ou sistemas autorizados. Integridade significa que dados permanecem corretos e não são alterados indevidamente. Disponibilidade significa que sistemas e informações podem ser utilizados quando necessários.","Os três objetivos podem entrar em tensão. Uma proteção muito restritiva pode reduzir disponibilidade; um serviço altamente disponível pode ampliar superfície de ataque; cópias de segurança protegem disponibilidade, mas precisam de controles para preservar confidencialidade e integridade."]},
      {heading:"2. Ameaças, vulnerabilidades e riscos",paragraphs:["Ameaça é uma circunstância ou agente capaz de causar dano. Vulnerabilidade é uma fraqueza que pode ser explorada. Risco combina probabilidade e impacto em determinado contexto. Uma ameaça não é o mesmo que uma vulnerabilidade: um phishing é uma técnica de ataque; reutilização de senhas pode ser uma fragilidade explorável.","Modelo de ameaças é um processo estruturado para identificar ativos, agentes, objetivos, pontos de entrada, limites de confiança e controles. Ele ajuda a priorizar proteção com base em cenários concretos, em vez de instalar ferramentas sem entender o problema."]},
      {heading:"3. Controles proporcionais",paragraphs:["Controles comuns incluem autenticação multifator, princípio do menor privilégio, atualização, criptografia, backups testados, registro de eventos, segmentação de rede, treinamento e plano de resposta a incidentes. Nenhum controle isolado resolve tudo.","A resposta a incidentes deve prever identificação, contenção, erradicação, recuperação e lições aprendidas. Em ambientes reais, preserve evidências, documente ações e observe obrigações legais e contratuais, especialmente quando dados pessoais estiverem envolvidos."]}
    ],
    keyTerms:[{term:"Confidencialidade",definition:"Acesso à informação restrito a entidades autorizadas."},{term:"Integridade",definition:"Preservação da exatidão e completude de dados e sistemas."},{term:"Disponibilidade",definition:"Acesso confiável a sistemas e informações quando necessário."},{term:"Vulnerabilidade",definition:"Fraqueza que pode ser explorada por uma ameaça."}],
    caseStudy:"Uma pequena imobiliária armazena documentos de clientes em uma conta compartilhada, sem autenticação multifator e com senha repetida em vários serviços. Um funcionário sai da empresa, mas mantém acesso. Identifique ativos, ameaças, vulnerabilidades e controles prioritários antes de comprar qualquer solução.",
    question:{prompt:"Qual situação representa principalmente uma falha de confidencialidade?",options:["Um sistema fica indisponível durante uma manutenção.","Um arquivo é alterado sem autorização.","Dados pessoais são acessados por alguém sem permissão.","Uma cópia de segurança não foi concluída."],correct:2,explanation:"Acesso não autorizado a dados compromete confidencialidade; alteração indevida compromete integridade e indisponibilidade afeta disponibilidade."},
    reflection:"Escolha um serviço digital que você usa. Liste três ativos importantes, duas ameaças plausíveis e um controle proporcional para cada risco.",
    references:["NIST. Cybersecurity Framework 2.0: https://www.nist.gov/cyberframework.","OWASP Cheat Sheet Series: https://cheatsheetseries.owasp.org/.","ANPD. Guia orientativo de segurança da informação para agentes de tratamento de pequeno porte."]
  },
  {
    id:"his-10", title:"Revolução Industrial e transformação do trabalho", duration:55,
    objective:"Analisar as mudanças tecnológicas, econômicas e sociais da industrialização e suas consequências de longo prazo.",
    sections:[
      {heading:"1. Industrialização como processo histórico",paragraphs:["A Revolução Industrial começou na Grã-Bretanha no século XVIII e se expandiu de forma desigual para outras regiões. Não foi um evento isolado, mas um processo que combinou mecanização, novas fontes de energia, concentração produtiva, mudanças agrícolas, expansão comercial, instituições e disponibilidade de capital.","A máquina a vapor, a indústria têxtil, a mineração e, posteriormente, ferrovias transformaram produção e transporte. A cronologia e os setores variaram entre países, de modo que não existe uma única experiência industrial universal."]},
      {heading:"2. Trabalho, cidade e conflito social",paragraphs:["A fábrica concentrou trabalhadores, máquinas e disciplina temporal. Jornadas longas, acidentes, trabalho infantil e baixos salários fizeram parte de muitas experiências iniciais. Ao mesmo tempo, a industrialização ampliou a produção, transformou mercados e estimulou urbanização e novas formas de organização social.","Associações de trabalhadores, sindicatos, movimentos políticos e reformas legais responderam às condições de trabalho. Direitos trabalhistas não surgiram automaticamente com a tecnologia: foram resultado de conflitos, mobilização, negociação e mudanças institucionais."]},
      {heading:"3. Industrialização, desigualdade e ambiente",paragraphs:["Os ganhos de produtividade foram distribuídos de forma desigual entre classes sociais, regiões e países. A industrialização também ampliou a extração de recursos e a poluição, criando impactos ambientais que se acumularam ao longo do tempo.","A comparação histórica exige perguntar quem controlava tecnologias e capital, quem assumia custos, como se distribuíam ganhos e quais alternativas existiam. Evite explicações monocausais: tecnologia, instituições, política, comércio e relações de poder interagiram."]}
    ],
    keyTerms:[{term:"Mecanização",definition:"Substituição ou ampliação do trabalho humano por máquinas e sistemas mecânicos."},{term:"Urbanização",definition:"Crescimento da população urbana e transformação das cidades."},{term:"Produtividade",definition:"Relação entre produção obtida e recursos utilizados."},{term:"Proletariado",definition:"Classe de trabalhadores que depende principalmente da venda de sua força de trabalho."}],
    caseStudy:"Uma região recebe uma grande fábrica automatizada. A produção cresce, mas alguns empregos tradicionais desaparecem e novas funções exigem qualificação técnica. Analise efeitos sobre salários, formação profissional, organização sindical, arrecadação, ambiente e distribuição dos ganhos.",
    question:{prompt:"Por que a Revolução Industrial deve ser entendida como processo e não como invenção isolada?",options:["Porque envolveu mudanças tecnológicas, econômicas, institucionais e sociais interligadas.","Porque ocorreu ao mesmo tempo e da mesma forma em todos os países.","Porque não alterou relações de trabalho nem padrões urbanos.","Porque dependeu exclusivamente da máquina a vapor."],correct:0,explanation:"A industrialização resultou da interação de tecnologias, capital, mercados, instituições, energia e transformações sociais ao longo do tempo."},
    reflection:"Compare uma transformação tecnológica atual com a industrialização. Quais grupos podem ganhar, perder ou precisar se adaptar? Que evidências sustentariam sua análise?",
    references:["HOBSBAWM, Eric. A Era das Revoluções: 1789–1848. Paz e Terra.","ALLEN, Robert C. The British Industrial Revolution in Global Perspective. Cambridge University Press.","Our World in Data — Economic Growth: https://ourworldindata.org/economic-growth."]
  },
  {
    id:"his-11", title:"Geopolítica: território, poder e recursos estratégicos", duration:55,
    objective:"Utilizar conceitos de território, soberania, recursos e interdependência para interpretar disputas geopolíticas sem reducionismos.",
    sections:[
      {heading:"1. Espaço e poder",paragraphs:["Geopolítica estuda relações entre poder político, espaço geográfico, recursos, infraestrutura e estratégias de atores estatais e não estatais. Território não é apenas área física: envolve população, fronteiras, instituições, identidade, circulação e controle de recursos.","A localização pode influenciar acesso a rotas marítimas, mercados, energia e zonas de segurança. Mas geografia não determina sozinha decisões políticas; tecnologia, economia, alianças, história e escolhas institucionais também importam."]},
      {heading:"2. Soberania e interdependência",paragraphs:["Soberania refere-se à autoridade política de um Estado sobre seu território e à sua independência jurídica nas relações externas, dentro das normas internacionais. Na prática, Estados dependem uns dos outros em comércio, finanças, energia, tecnologia, alimentos e segurança.","Interdependência pode criar cooperação, mas também vulnerabilidades. Uma cadeia produtiva concentrada em poucos fornecedores pode tornar um país sensível a sanções, conflitos, desastres ou decisões comerciais externas."]},
      {heading:"3. Recursos, rotas e infraestrutura",paragraphs:["Petróleo, gás, minerais críticos, água, alimentos, cabos submarinos, portos, canais, satélites e semicondutores podem ter importância estratégica. O valor geopolítico depende de disponibilidade, substituibilidade, concentração, custo de transporte e capacidade de processamento.","Ao analisar uma disputa, identifique atores, interesses declarados e materiais, capacidades, dependências, instituições, narrativas e evidências. Diferencie fatos observáveis de hipóteses sobre intenções, que costumam ser mais difíceis de demonstrar."]}
    ],
    keyTerms:[{term:"Território",definition:"Espaço apropriado, organizado ou controlado por relações de poder e instituições."},{term:"Soberania",definition:"Autoridade política do Estado no plano interno e independência jurídica no plano externo, sujeitas ao Direito Internacional."},{term:"Interdependência",definition:"Relação de dependência recíproca entre atores, setores ou países."},{term:"Geoeconomia",definition:"Uso de instrumentos econômicos e comerciais para objetivos estratégicos e de poder."}],
    caseStudy:"Uma crise interrompe o fornecimento de um mineral usado em baterias. Países importadores avaliam estoques, fornecedores alternativos, reciclagem, produção doméstica e acordos comerciais. O caso mostra como cadeias de suprimento, tecnologia e política externa se conectam.",
    question:{prompt:"Qual abordagem é mais adequada para analisar uma disputa geopolítica?",options:["Atribuir o conflito a uma única característica geográfica.","Identificar atores, interesses, capacidades, dependências e evidências históricas e institucionais.","Aceitar toda declaração oficial como descrição completa dos fatos.","Ignorar economia e tecnologia porque geopolítica trata apenas de fronteiras."],correct:1,explanation:"A análise geopolítica combina geografia, poder, economia, tecnologia, história e evidências, evitando explicações monocausais."},
    reflection:"Escolha um recurso estratégico e mapeie três países ou regiões envolvidos em sua produção, processamento ou consumo. Onde estão as dependências e quais dados faltam?",
    references:["ONU — Carta das Nações Unidas: https://www.un.org/en/about-us/un-charter.","International Energy Agency: https://www.iea.org/.","World Bank Data: https://data.worldbank.org/."]
  },
  {
    id:"fil-10", title:"Lógica informal: argumentos, premissas e falácias", duration:50,
    objective:"Reconstruir argumentos cotidianos, distinguir validade de persuasão e identificar falácias frequentes com cautela.",
    sections:[
      {heading:"1. Como reconhecer um argumento",paragraphs:["Um argumento é um conjunto de afirmações em que algumas — premissas — são apresentadas como razões para aceitar outra — conclusão. Nem todo texto persuasivo contém um argumento explícito, e nem toda sequência de frases é um raciocínio bem formado.","Reconstruir um argumento exige identificar a conclusão principal, explicitar premissas implícitas e verificar se as razões realmente sustentam a conclusão. Uma premissa pode ser verdadeira e ainda assim irrelevante para a conclusão; pode também ser relevante, mas insuficiente."]},
      {heading:"2. Validade, força e verdade",paragraphs:["Na lógica dedutiva, um argumento é válido quando não é possível que todas as premissas sejam verdadeiras e a conclusão falsa. Validade não garante que as premissas sejam verdadeiras. Um argumento sólido é válido e possui premissas verdadeiras.","Em argumentos indutivos e abdutivos, as premissas tornam a conclusão mais ou menos provável, sem garanti-la logicamente. Nesses casos, avalie qualidade da amostra, alternativas explicativas, contexto, confiabilidade das fontes e grau de incerteza."]},
      {heading:"3. Falácias e diagnóstico",paragraphs:["Falácias são padrões de raciocínio que parecem apoiar uma conclusão, mas falham em algum aspecto relevante. Ataque pessoal, falsa dicotomia, generalização apressada, espantalho e apelo indevido à autoridade são exemplos comuns.","O rótulo de falácia não substitui a análise. Uma afirmação pode conter um ataque pessoal e ainda ter uma conclusão verdadeira por outras razões; uma autoridade pode ser relevante quando possui competência específica e a fonte é adequada. Examine a estrutura e as evidências, não apenas o nome da falácia."]}
    ],
    keyTerms:[{term:"Premissa",definition:"Afirmação oferecida como razão para sustentar uma conclusão."},{term:"Conclusão",definition:"Afirmação que o argumento procura justificar."},{term:"Validade",definition:"Propriedade de um argumento dedutivo cuja conclusão decorre necessariamente das premissas."},{term:"Falácia",definition:"Padrão de raciocínio que compromete a força justificativa de um argumento."}],
    caseStudy:"Um comentário diz: 'O especialista errou uma previsão; portanto, todas as suas pesquisas são inúteis'. Reconstrua a conclusão e as premissas. Avalie se um erro específico permite descartar todo o trabalho, e quais evidências seriam necessárias para julgar a confiabilidade geral do especialista.",
    question:{prompt:"O que significa dizer que um argumento dedutivo é válido?",options:["Que todas as suas premissas são necessariamente verdadeiras.","Que a conclusão decorre necessariamente das premissas, se elas forem verdadeiras.","Que a conclusão parece convincente para a maioria das pessoas.","Que o argumento foi apresentado por uma autoridade."],correct:1,explanation:"Validade é uma relação entre premissas e conclusão; não garante por si só a verdade das premissas."},
    reflection:"Escolha uma afirmação de debate público. Escreva a conclusão, duas premissas explícitas ou implícitas e uma evidência que poderia enfraquecer o argumento.",
    references:["COPI, Irving M.; COHEN, Carl. Introdução à Lógica. Martins Fontes.","Internet Encyclopedia of Philosophy — Informal Logic: https://iep.utm.edu/.","Stanford Encyclopedia of Philosophy — Fallacies: https://plato.stanford.edu/."]
  },
  {
    id:"fil-11", title:"Epistemologia: conhecimento, evidência e ceticismo", duration:55,
    objective:"Distinguir crença, verdade e justificação e avaliar como evidências sustentam afirmações em diferentes contextos.",
    sections:[
      {heading:"1. O que significa conhecer",paragraphs:["A epistemologia investiga a natureza, as fontes, os limites e a justificação do conhecimento. Uma distinção clássica separa crença, verdade e justificação: acreditar em uma proposição não a torna verdadeira, e acertar por acaso não parece suficiente para caracterizar conhecimento.","A tradição filosófica debate se conhecimento pode ser definido como crença verdadeira justificada e quais problemas surgem para essa proposta. O objetivo introdutório não é decorar uma definição única, mas compreender por que verdade, evidência, confiabilidade e sorte epistêmica precisam ser examinadas."]},
      {heading:"2. Fontes e tipos de evidência",paragraphs:["Percepção, memória, testemunho, introspecção e raciocínio são fontes comuns de crenças. Cada uma possui condições de confiabilidade e possibilidade de erro. Em pesquisa empírica, observações, medições, experimentos e dados documentais precisam de procedimentos que permitam crítica e reprodução quando apropriado.","Evidência deve ser avaliada em relação à pergunta. Um depoimento pode ser relevante para saber o que alguém presenciou, mas insuficiente para estimar a frequência de um fenômeno na população. Uma correlação pode indicar associação sem demonstrar causalidade."]},
      {heading:"3. Ceticismo e revisão racional",paragraphs:["Ceticismo filosófico questiona se determinadas crenças podem ser justificadas ou se existe conhecimento seguro em certos domínios. Na vida prática, ceticismo metodológico significa calibrar confiança, buscar fontes independentes, distinguir observação de inferência e revisar crenças diante de evidências melhores.","Não é racional exigir certeza absoluta para toda afirmação. Diferentes decisões exigem diferentes padrões de evidência: uma hipótese exploratória, uma decisão clínica, uma condenação penal e uma política pública têm consequências e critérios próprios."]}
    ],
    keyTerms:[{term:"Crença",definition:"Atitude de aceitar uma proposição como verdadeira."},{term:"Justificação",definition:"Razões ou evidências que sustentam racionalmente uma crença."},{term:"Evidência",definition:"Informação relevante para avaliar a verdade ou plausibilidade de uma afirmação."},{term:"Ceticismo",definition:"Postura crítica que questiona a possibilidade, o alcance ou a justificação do conhecimento."}],
    caseStudy:"Uma postagem afirma que um alimento 'previne uma doença' e apresenta o relato de uma pessoa que melhorou após consumi-lo. O relato pode gerar uma hipótese, mas não controla outras causas, evolução natural ou seleção de casos. Para avaliar a afirmação, procure estudos comparativos, qualidade metodológica e consenso científico atualizado.",
    question:{prompt:"Por que um relato individual não é suficiente para provar que um alimento previne uma doença?",options:["Porque relatos nunca têm qualquer valor informativo.","Porque um caso isolado não controla explicações alternativas nem permite estimar causalidade.","Porque apenas autoridades podem produzir conhecimento.","Porque toda evidência científica é absolutamente certa."],correct:1,explanation:"Relatos podem sugerir hipóteses, mas não isolam causas nem estimam efeitos de modo confiável."},
    reflection:"Escolha uma afirmação que você considera verdadeira. Quais evidências a sustentam? O que faria você mudar de opinião e qual nível de confiança seria adequado?",
    references:["Stanford Encyclopedia of Philosophy — Epistemology: https://plato.stanford.edu/entries/epistemology/.","Internet Encyclopedia of Philosophy — Epistemology: https://iep.utm.edu/epistemo/.","National Academies — Reproducibility and Replicability in Science: https://nap.nationalacademies.org/catalog/25303/reproducibility-and-replicability-in-science."]
  },
  {
    id:"cie-10", title:"Estatística descritiva: médias, dispersão e leitura crítica", duration:50,
    objective:"Resumir conjuntos de dados usando medidas de tendência central e dispersão e reconhecer limites de interpretação.",
    sections:[
      {heading:"1. Organizar antes de calcular",paragraphs:["Estatística descritiva organiza e resume dados observados. Antes de calcular, identifique população, amostra, unidade de análise, variável, período e método de coleta. Um número sem unidade ou contexto pode induzir a erro.","Tabelas de frequência e gráficos ajudam a observar distribuição, valores extremos, lacunas e possíveis erros. A escolha do gráfico deve respeitar o tipo de variável: barras para categorias, histogramas para distribuições numéricas e linhas para séries temporais, entre outras possibilidades."]},
      {heading:"2. Média, mediana e moda",paragraphs:["A média aritmética soma os valores e divide pela quantidade de observações. É sensível a valores extremos. A mediana é o valor central após ordenar os dados e costuma representar melhor distribuições assimétricas. A moda é o valor ou categoria mais frequente.","Não existe medida universalmente superior. Para renda, por exemplo, poucos valores muito altos podem elevar a média; a mediana frequentemente descreve melhor o valor central da distribuição. A pergunta de pesquisa orienta a escolha da medida."]},
      {heading:"3. Dispersão e comparação",paragraphs:["Amplitude, variância, desvio-padrão e intervalo interquartil descrevem diferentes aspectos da dispersão. Duas turmas podem ter a mesma média e distribuições muito diferentes. A dispersão informa quão concentrados ou espalhados estão os valores.","Comparações exigem atenção à escala, tamanho da amostra, período, composição dos grupos e incerteza. Uma diferença observada não prova, por si só, que um grupo causou o resultado do outro."]}
    ],
    keyTerms:[{term:"Média",definition:"Soma dos valores dividida pelo número de observações."},{term:"Mediana",definition:"Valor central de dados ordenados, ou média dos dois centrais quando a quantidade é par."},{term:"Moda",definition:"Valor ou categoria que ocorre com maior frequência."},{term:"Desvio-padrão",definition:"Medida de dispersão que expressa a variação típica em torno da média, nas mesmas unidades dos dados."}],
    caseStudy:"Duas cidades apresentam renda média semelhante, mas a primeira possui mediana muito menor. Isso pode indicar concentração de renda em poucos valores elevados. Para compreender a desigualdade, examine distribuição, quantis, composição domiciliar, custo de vida e fonte dos dados.",
    question:{prompt:"Quando a mediana pode ser mais representativa que a média?",options:["Quando há valores extremos que distorcem a média em uma distribuição assimétrica.","Quando todos os valores são exatamente iguais.","Quando não existem dados ordenáveis.","Sempre, independentemente da pergunta."],correct:0,explanation:"A mediana é menos sensível a valores extremos e pode representar melhor o centro de distribuições assimétricas."},
    reflection:"Encontre uma tabela pública do IBGE. Identifique variável, unidade, período e população observada. Que medida resumiria melhor os dados e por quê?",
    references:["IBGE — Indicadores e pesquisas: https://www.ibge.gov.br/.","OpenStax — Introductory Statistics 2e: https://openstax.org/details/books/introductory-statistics-2e/.","NIST/SEMATECH — e-Handbook of Statistical Methods: https://www.itl.nist.gov/div898/handbook/."]
  },
  {
    id:"cie-11", title:"Método científico: hipóteses, testes e limites", duration:55,
    objective:"Descrever etapas de uma investigação científica e avaliar hipóteses, variáveis, evidências e limites de inferência.",
    sections:[
      {heading:"1. Perguntas investigáveis",paragraphs:["A ciência não começa necessariamente com uma sequência rígida de etapas, mas com problemas e perguntas que podem ser investigados por métodos adequados. Uma boa pergunta delimita fenômeno, população, contexto e variáveis relevantes.","Hipóteses são explicações ou previsões que podem ser confrontadas com observações. Uma hipótese científica precisa gerar expectativas observáveis e estar aberta à revisão. Nem toda pergunta científica exige experimento controlado: história, astronomia, ecologia e ciências sociais utilizam estratégias metodológicas diferentes."]},
      {heading:"2. Variáveis, controles e causalidade",paragraphs:["Em um experimento, a variável independente é manipulada ou comparada e a variável dependente é medida. Variáveis de confusão podem influenciar tanto a exposição quanto o resultado. Randomização, grupos de comparação, cegamento e protocolos prévios ajudam a reduzir vieses, quando viáveis e éticos.","Correlação indica que duas variáveis variam juntas, mas não prova que uma cause a outra. Causalidade exige desenho e evidência capazes de lidar com temporalidade, mecanismos e explicações alternativas. Em estudos observacionais, métodos estatísticos podem ajudar, mas dependem de pressupostos que precisam ser explicitados."]},
      {heading:"3. Evidência, revisão e comunicação",paragraphs:["Resultados científicos precisam ser documentados com métodos, dados e limitações. Revisão por pares é um mecanismo de crítica, não garantia absoluta de correção. Replicação, reanálise, transparência e convergência de evidências fortalecem conclusões.","A comunicação responsável distingue resultado, interpretação e especulação. Uma pesquisa isolada raramente encerra um debate complexo. Avalie tamanho da amostra, qualidade da medição, financiamento, conflitos de interesse, incerteza e compatibilidade com o conjunto da literatura."]}
    ],
    keyTerms:[{term:"Hipótese",definition:"Proposição explicativa ou preditiva que pode ser confrontada com evidências."},{term:"Variável de confusão",definition:"Fator associado à exposição e ao resultado que pode distorcer a estimativa de uma relação."},{term:"Reprodutibilidade",definition:"Possibilidade de obter resultados consistentes ao repetir análises com os mesmos dados e métodos, conforme o contexto."},{term:"Correlação",definition:"Medida de associação entre variáveis, que não implica automaticamente causalidade."}],
    caseStudy:"Uma pesquisa observa que pessoas que tomam determinado suplemento apresentam melhor desempenho. Talvez sejam também mais ativas, tenham renda maior ou cuidem mais da saúde. Antes de atribuir causalidade ao suplemento, é necessário avaliar desenho, fatores de confusão, qualidade de medição e estudos independentes.",
    question:{prompt:"Qual afirmação é correta sobre correlação?",options:["Correlação prova que uma variável causa a outra.","Correlação indica associação, mas causalidade exige evidências e desenho adequados.","Correlação só pode existir em experimentos laboratoriais.","Uma correlação alta elimina a necessidade de analisar variáveis de confusão."],correct:1,explanation:"Associação estatística não basta para demonstrar causalidade; explicações alternativas e desenho do estudo precisam ser avaliados."},
    reflection:"Formule uma pergunta científica sobre um hábito cotidiano. Defina uma hipótese, o que seria medido, possíveis fatores de confusão e um limite ético ou prático do estudo.",
    references:["National Academies — Science and Engineering for Grades 6–12: https://nap.nationalacademies.org/.","NASA — Science: https://science.nasa.gov/.","OpenStax — Concepts of Biology: https://openstax.org/details/books/concepts-biology."]
  }

  ,{
    id:"direito-13",title:"Direito do consumidor e proteção nas relações de consumo",duration:50,
    objective:"Reconhecer a relação de consumo, os direitos básicos do consumidor e os caminhos iniciais para lidar com problemas de produtos e serviços.",
    sections:[
      {heading:"1. Quem é consumidor e fornecedor?",paragraphs:["O Código de Defesa do Consumidor organiza a proteção de pessoas que adquirem ou utilizam produtos e serviços como destinatárias finais, dentro dos conceitos legais. Fornecedor é a pessoa ou entidade que desenvolve atividades de produção, montagem, criação, construção, transformação, importação, distribuição ou comercialização, ou presta serviços, conforme a lei.","A identificação da relação de consumo depende dos fatos e das definições legais. Nem todo contrato é automaticamente uma relação de consumo; é necessário examinar quem participa, a finalidade da aquisição e a atividade envolvida."]},
      {heading:"2. Informação, segurança e responsabilidade",paragraphs:["Entre os direitos básicos estão informação adequada e clara, proteção contra publicidade enganosa ou abusiva, prevenção e reparação de danos e facilitação da defesa de direitos. A informação deve permitir que a pessoa compreenda características, preço, riscos e condições relevantes.","A responsabilidade por vício do produto ou serviço e a responsabilidade por fato do produto ou serviço possuem regimes próprios. Prazos, excludentes e providências variam conforme o problema. Guardar nota fiscal, contrato, mensagens, protocolos e registros do defeito ajuda a documentar a reclamação."]},
      {heading:"3. Como encaminhar um problema",paragraphs:["Um roteiro inicial consiste em registrar o ocorrido, identificar o fornecedor, reunir documentos, formular pedido objetivo e guardar o protocolo. Se não houver solução, podem existir canais como Procon, consumidor.gov.br e, conforme o caso, Juizados Especiais ou assistência jurídica.","O canal adequado depende do valor, da complexidade, dos prazos e do tipo de dano. Não se deve prometer resultado: a análise concreta exige documentos e consulta à legislação vigente."]}
    ],
    keyTerms:[{term:"Consumidor",definition:"Pessoa que adquire ou utiliza produto ou serviço como destinatária final, nos termos do CDC."},{term:"Fornecedor",definition:"Pessoa ou entidade que exerce atividade de produção, distribuição, comercialização ou prestação de serviços, conforme o CDC."},{term:"Vício",definition:"Problema de qualidade ou quantidade que torna o produto ou serviço inadequado ou diminui seu valor, nos termos legais."}],
    caseStudy:"Uma geladeira apresenta defeito poucos dias após a compra. O consumidor possui nota fiscal, fotos e protocolo de atendimento. A análise deve identificar o fornecedor, a natureza do problema, o prazo legal aplicável e as providências previstas no CDC, sem confundir vício com acidente de consumo.",
    question:{prompt:"Qual atitude fortalece a documentação de uma reclamação de consumo?",options:["Apagar mensagens para evitar conflito.","Guardar comprovante, registros do problema e protocolos de atendimento.","Aceitar qualquer proposta sem ler as condições.","Publicar dados pessoais do atendente na internet."],correct:1,explanation:"Documentos e protocolos ajudam a demonstrar a compra, o defeito, as tentativas de solução e a cronologia."},
    reflection:"Descreva uma situação hipotética de consumo e monte uma sequência de providências documentais e administrativas. Quais fatos ainda precisariam ser comprovados?",
    references:["BRASIL. Lei nº 8.078/1990 — Código de Defesa do Consumidor.","Secretaria Nacional do Consumidor — https://www.gov.br/mj/pt-br/assuntos/seus-direitos/consumidor.","Consumidor.gov.br — https://www.consumidor.gov.br/"]
  },
  {
    id:"eco-12",title:"Macroeconomia: PIB, desemprego e ciclo econômico",duration:55,
    objective:"Interpretar indicadores macroeconômicos básicos e reconhecer o que eles mostram e o que deixam de mostrar.",
    sections:[
      {heading:"1. Produto Interno Bruto",paragraphs:["O Produto Interno Bruto mede o valor dos bens e serviços finais produzidos em determinado território e período, segundo regras de contabilidade nacional. Pode ser calculado pelas óticas da produção, da despesa ou da renda, que devem convergir conceitualmente quando os dados estão completos.","PIB nominal usa preços correntes; PIB real procura retirar o efeito da variação de preços para acompanhar mudanças no volume produzido. PIB per capita divide o produto pela população, mas não informa como a renda está distribuída nem mede sozinho bem-estar, segurança ou qualidade ambiental."]},
      {heading:"2. Mercado de trabalho e ciclo",paragraphs:["Indicadores de emprego e desemprego dependem de definições estatísticas sobre ocupação, procura por trabalho e disponibilidade. Taxa de desemprego não inclui todas as formas de subutilização da força de trabalho, como pessoas subocupadas ou desalentadas, que precisam ser examinadas em medidas complementares.","Ciclos econômicos envolvem períodos de expansão e desaceleração da atividade. Consumo, investimento, gasto público, exportações, crédito, expectativas e choques externos podem influenciar o ritmo. A duração e a intensidade dos ciclos variam; não há uma causa única para toda recessão."]},
      {heading:"3. Indicadores não são diagnósticos completos",paragraphs:["Um indicador resume uma dimensão da economia. Para interpretar uma notícia, confira fonte, período, unidade, ajuste sazonal, revisão da série e comparação adequada. Uma alta trimestral pode coexistir com queda em outro setor ou com distribuição desigual dos ganhos.","A análise macroeconômica combina indicadores e mecanismos. Evite transformar uma correlação entre duas séries em causalidade sem examinar defasagens, fatores externos e explicações alternativas."]}
    ],
    keyTerms:[{term:"PIB",definition:"Valor dos bens e serviços finais produzidos em uma economia durante determinado período."},{term:"PIB real",definition:"Medida do produto ajustada para separar variações de volume das variações de preços."},{term:"Desemprego",definition:"Condição estatística definida por critérios de ocupação, procura e disponibilidade para trabalhar."},{term:"Ciclo econômico",definition:"Oscilações da atividade econômica em fases de expansão e contração."}],
    caseStudy:"Uma manchete afirma que o PIB cresceu 2% e conclui que todas as famílias estão 2% mais ricas. A conclusão é indevida: PIB mede produção agregada, não renda de cada pessoa. É preciso examinar PIB per capita, distribuição, inflação, emprego, salários e custo de vida.",
    question:{prompt:"Por que crescimento do PIB não significa automaticamente melhora igual para todas as pessoas?",options:["Porque o PIB mede somente a renda de cada família.","Porque o crescimento agregado não informa como os ganhos são distribuídos nem todas as dimensões do bem-estar.","Porque o PIB não considera produção de bens e serviços.","Porque qualquer crescimento econômico reduz necessariamente os salários."],correct:1,explanation:"O PIB é uma medida agregada de produção; distribuição de renda e outras dimensões sociais exigem indicadores adicionais."},
    reflection:"Escolha uma notícia econômica recente e identifique o indicador, a fonte, o período e duas informações adicionais necessárias para avaliar o impacto sobre famílias.",
    references:["IBGE — Contas Nacionais: https://www.ibge.gov.br/estatisticas/economicas/contas-nacionais.html.","IBGE — Pesquisa Nacional por Amostra de Domicílios Contínua: https://www.ibge.gov.br/estatisticas/sociais/trabalho.html.","Banco Central do Brasil — Indicadores econômicos: https://www.bcb.gov.br/estatisticas."]
  },
  {
    id:"tec-12",title:"Fundamentos de programação: variáveis, condições e repetição",duration:55,
    objective:"Compreender a lógica básica de um programa e decompor um problema em instruções, decisões e repetições.",
    sections:[
      {heading:"1. Programa como sequência de instruções",paragraphs:["Programar é expressar um procedimento de resolução de problemas em uma linguagem que um computador possa executar. Antes de escolher a linguagem, é útil definir entradas, processamento e saídas esperadas. Um algoritmo descreve uma sequência finita e organizada de passos.","Variáveis representam valores que podem ser consultados ou alterados durante a execução. Tipos de dados definem operações possíveis e ajudam a evitar erros, como somar texto a números sem conversão adequada."]},
      {heading:"2. Decisões e repetição",paragraphs:["Estruturas condicionais permitem executar caminhos diferentes conforme uma expressão lógica seja verdadeira ou falsa. Por exemplo, um sistema pode verificar se uma idade atende a um requisito antes de liberar uma etapa. A condição deve ser explícita e testada também nos casos-limite.","Laços de repetição executam um bloco várias vezes. Um laço pode percorrer uma lista, repetir enquanto uma condição for verdadeira ou executar uma quantidade definida de vezes. É necessário garantir uma condição de parada para evitar ciclos infinitos."]},
      {heading:"3. Decomposição e testes",paragraphs:["Problemas maiores devem ser divididos em partes menores, com funções que tenham responsabilidades claras. Essa decomposição facilita leitura, manutenção e testes. Nomes significativos e comentários úteis tornam o código mais compreensível.","Testar significa verificar o comportamento em entradas normais, limites e situações inesperadas. Um programa que funciona para um único exemplo ainda pode falhar em outros. Testes não provam ausência total de defeitos, mas ajudam a encontrar problemas antes que afetem usuários."]}
    ],
    keyTerms:[{term:"Algoritmo",definition:"Sequência finita e organizada de instruções para resolver uma classe de problemas."},{term:"Variável",definition:"Nome associado a um valor armazenado ou manipulado durante a execução."},{term:"Condicional",definition:"Estrutura que escolhe um caminho de execução com base em uma condição lógica."},{term:"Laço",definition:"Estrutura que repete instruções enquanto uma condição ou regra de iteração for satisfeita."}],
    caseStudy:"Uma imobiliária deseja calcular comissão: o sistema recebe o valor da venda e a taxa contratada, verifica se os dados são válidos e calcula o resultado. Decomponha o problema em entradas, validações, processamento e saída. Considere valores nulos, negativos e taxas fora do intervalo esperado.",
    question:{prompt:"Qual é a função de uma estrutura condicional?",options:["Repetir instruções indefinidamente.","Escolher um caminho de execução conforme uma condição lógica.","Armazenar permanentemente todos os dados do computador.","Converter automaticamente qualquer linguagem em hardware."],correct:1,explanation:"Condicionais permitem que o programa tome decisões com base em expressões verdadeiras ou falsas."},
    reflection:"Escreva em linguagem natural um algoritmo para verificar se uma despesa cabe no orçamento mensal. Identifique variáveis, condições e casos de teste.",
    references:["CS50x — Introduction to Computer Science: https://cs50.harvard.edu/x/.","MDN — JavaScript Guide: https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide.","Python — Tutorial oficial: https://docs.python.org/pt-br/3/tutorial/."]
  },
  {
    id:"his-12",title:"História do Brasil: colonização, escravidão e formação do Estado",duration:60,
    objective:"Analisar processos centrais da formação histórica brasileira e suas continuidades sociais, econômicas e institucionais.",
    sections:[
      {heading:"1. Colonização e economia",paragraphs:["A colonização portuguesa na América foi marcada por ocupação territorial, exploração econômica, disputas imperiais e relações complexas com povos indígenas. A produção colonial variou regionalmente e articulou agricultura, mineração, pecuária, comércio e redes atlânticas.","A escravidão africana e indígena foi estruturante para a economia e a sociedade coloniais. O tráfico transatlântico deslocou milhões de africanos à força e produziu violência, resistência, formação cultural e desigualdades duradouras. Não se deve tratar a escravidão como simples mão de obra sem considerar suas dimensões humanas e políticas."]},
      {heading:"2. Independência e construção do Estado",paragraphs:["A independência de 1822 resultou de processos políticos, conflitos e negociações no contexto da crise do sistema colonial e das revoluções atlânticas. Não significou ruptura imediata de todas as estruturas sociais: a monarquia foi mantida e a escravidão permaneceu até 1888.","O Estado imperial enfrentou disputas regionais, revoltas, centralização e construção de instituições. A proclamação da República em 1889 abriu outro arranjo político, também marcado por exclusões e disputas sobre cidadania, representação e poder local."]},
      {heading:"3. Abolição, cidadania e desigualdade",paragraphs:["A abolição foi resultado de resistência negra, fugas, quilombos, mobilização abolicionista, mudanças econômicas e pressões políticas. A Lei Áurea encerrou juridicamente a escravidão, mas não veio acompanhada de políticas amplas de reparação, inclusão econômica e acesso à terra para a população liberta.","A interpretação histórica precisa confrontar fontes, reconhecer diferentes sujeitos e evitar narrativas que apresentem mudanças como concessões espontâneas de elites. A formação do Brasil envolve conflitos, negociações e projetos de sociedade em disputa."]}
    ],
    keyTerms:[{term:"Colonização",definition:"Processo de ocupação e dominação territorial, política e econômica por uma potência externa."},{term:"Escravidão",definition:"Sistema de exploração que transforma pessoas em propriedade ou as submete coercitivamente a trabalho e controle, com formas históricas específicas."},{term:"Abolicionismo",definition:"Movimentos e ações políticas e sociais voltados ao fim da escravidão."},{term:"Cidadania",definition:"Condição de participação política e titularidade de direitos e deveres em uma comunidade política."}],
    caseStudy:"Um livro didático afirma que a abolição ocorreu porque a princesa assinou a lei. A lei é um marco jurídico, mas a explicação histórica precisa incluir resistência de pessoas escravizadas, movimentos abolicionistas, redes de apoio, conflitos, economia e pressões políticas.",
    question:{prompt:"Por que a Lei Áurea não encerrou automaticamente as desigualdades produzidas pela escravidão?",options:["Porque a lei manteve formalmente a escravidão por mais cem anos.","Porque o fim jurídico da escravidão não foi acompanhado de inclusão e reparação suficientes para eliminar estruturas sociais e econômicas.","Porque a escravidão não teve impacto na sociedade brasileira.","Porque a abolição ocorreu sem participação de pessoas escravizadas ou movimentos sociais."],correct:1,explanation:"A abolição legal não desfez automaticamente desigualdades acumuladas nem garantiu acesso à terra, renda, educação e direitos."},
    reflection:"Compare uma fonte oficial sobre a abolição com um relato ou estudo sobre resistência negra. O que cada fonte revela e quais vozes podem estar ausentes?",
    references:["Arquivo Nacional — Acervo e exposições: https://www.gov.br/arquivonacional/pt-br.","Fundação Biblioteca Nacional — Hemeroteca Digital: https://bndigital.bn.gov.br/hemeroteca-digital/.","SCHWARCZ, Lilia Moritz; STARLING, Heloisa Murgel. Brasil: uma biografia. Companhia das Letras."]
  },
  {
    id:"fil-12",title:"Filosofia política: Estado, liberdade e democracia",duration:55,
    objective:"Comparar concepções de Estado, liberdade e legitimidade política e formular critérios para avaliar instituições democráticas.",
    sections:[
      {heading:"1. Por que existe autoridade política?",paragraphs:["A filosofia política investiga a origem, a justificativa e os limites do poder coletivo. Teorias contratualistas, por exemplo, procuram explicar a autoridade política a partir de acordos hipotéticos ou fundamentos de consentimento, mas divergem sobre natureza humana, direitos, segurança e extensão do governo.","Hobbes enfatiza a necessidade de autoridade capaz de conter conflitos; Locke destaca direitos e governo limitado; Rousseau relaciona legitimidade à soberania popular e à vontade geral. Essas ideias não são descrições neutras da história, mas construções filosóficas que ajudam a comparar argumentos sobre poder."]},
      {heading:"2. Liberdade e igualdade",paragraphs:["Liberdade pode significar ausência de interferência, capacidade efetiva de agir ou participação no autogoverno. Essas concepções podem produzir avaliações diferentes de políticas públicas. Uma regra que impede interferência arbitrária pode proteger liberdade; condições materiais e acesso a oportunidades também podem influenciar a possibilidade real de escolha.","Igualdade pode envolver igualdade perante a lei, igualdade política, oportunidades ou condições sociais. Não há uma única fórmula simples: teorias políticas divergem sobre quais desigualdades são aceitáveis, quais exigem correção e quais direitos não podem ser sacrificados."]},
      {heading:"3. Democracia e instituições",paragraphs:["Democracia não se reduz ao voto periódico. Ela depende de competição política, liberdade de expressão e associação, acesso à informação, proteção de minorias, Estado de Direito, responsabilização e possibilidade de alternância no poder.","Instituições democráticas podem falhar e precisam de controles. Avaliar uma decisão exige examinar legalidade, transparência, participação, efeitos sobre direitos e mecanismos de revisão. Discordar de uma política não equivale, por si só, a rejeitar a democracia; o debate precisa respeitar regras e direitos que tornam a disputa possível."]}
    ],
    keyTerms:[{term:"Legitimidade",definition:"Justificação do direito de exercer poder ou da autoridade de uma instituição."},{term:"Liberdade negativa",definition:"Liberdade entendida como ausência de interferência ou coerção indevida."},{term:"Soberania popular",definition:"Princípio segundo o qual a autoridade política deriva do povo."},{term:"Estado de Direito",definition:"Modelo em que o poder público está submetido a normas, competências, direitos e mecanismos de controle."}],
    caseStudy:"Uma maioria eleita aprova uma medida que restringe a expressão de um grupo minoritário. O fato de ter sido aprovada por maioria não encerra a análise: examine direitos fundamentais, limites constitucionais, proporcionalidade, participação e mecanismos de controle.",
    question:{prompt:"Por que eleições, embora essenciais, não são suficientes para definir uma democracia constitucional?",options:["Porque democracia dispensa eleições e representação.","Porque também são necessários direitos, pluralismo, Estado de Direito, liberdade e controles sobre o poder.","Porque decisões majoritárias nunca possuem legitimidade.","Porque instituições de controle devem obedecer sempre ao governo de turno."],correct:1,explanation:"Democracia constitucional combina participação e competição política com direitos, limites ao poder e instituições de controle."},
    reflection:"Escolha uma política pública controversa. Analise-a por três critérios: legitimidade democrática, proteção de direitos e efeitos sobre grupos diferentes.",
    references:["LOCKE, John. Segundo Tratado sobre o Governo Civil.","ROUSSEAU, Jean-Jacques. Do Contrato Social.","Stanford Encyclopedia of Philosophy — Democracy: https://plato.stanford.edu/entries/democracy/."]
  },
  {
    id:"cie-12",title:"Física: movimento, força e leis de Newton",duration:55,
    objective:"Descrever movimento e aplicar as leis de Newton a situações simples, distinguindo velocidade, aceleração e força resultante.",
    sections:[
      {heading:"1. Descrever o movimento",paragraphs:["Cinemática descreve o movimento sem investigar inicialmente suas causas. Posição indica onde um corpo está em relação a um referencial; deslocamento é a variação da posição; velocidade relaciona deslocamento e tempo; aceleração descreve a variação da velocidade.","Rapidez é o módulo da velocidade e não informa direção. Um corpo pode manter rapidez constante e ainda apresentar aceleração se a direção da velocidade mudar, como ocorre no movimento circular uniforme."]},
      {heading:"2. As leis de Newton",paragraphs:["A primeira lei descreve a inércia: se a força resultante sobre um corpo é nula, ele permanece em repouso ou em movimento retilíneo uniforme em um referencial inercial. Força resultante não é necessária para manter movimento, mas para alterar o estado de movimento.","A segunda lei relaciona força resultante, massa e aceleração: em sua forma usual para massa constante, F = m·a. A terceira lei afirma que forças de interação aparecem em pares de mesma intensidade e direção, mas sentidos opostos, atuando em corpos diferentes."]},
      {heading:"3. Diagramas e aplicação",paragraphs:["Um diagrama de corpo livre representa as forças que atuam em um objeto, como peso, normal, atrito, tensão e força aplicada. O diagrama ajuda a separar forças reais de componentes matemáticas e evita somar forças que atuam em corpos diferentes.","A aplicação exige definir o sistema, escolher eixos, identificar forças e considerar unidades. O modelo idealizado pode ignorar resistência do ar ou deformações; declare essas hipóteses e avalie se são adequadas ao problema."]}
    ],
    keyTerms:[{term:"Velocidade",definition:"Grandeza vetorial que relaciona deslocamento e intervalo de tempo."},{term:"Aceleração",definition:"Taxa de variação da velocidade no tempo."},{term:"Inércia",definition:"Tendência de um corpo manter seu estado de movimento na ausência de força resultante."},{term:"Força resultante",definition:"Soma vetorial das forças que atuam sobre um corpo."}],
    caseStudy:"Um carro percorre uma curva com rapidez constante. A rapidez não muda, mas a direção da velocidade muda. Portanto, há aceleração centrípeta e uma força resultante direcionada para o centro da trajetória, fornecida por interações como atrito entre pneus e pista.",
    question:{prompt:"Um objeto se move em linha reta com velocidade constante. Qual é a força resultante idealizada sobre ele?",options:["Maior que o peso em todos os casos.","Nula, pois a aceleração é zero.","Sempre igual à massa multiplicada pela velocidade.","Necessariamente na direção do movimento."],correct:1,explanation:"Pela segunda lei de Newton, força resultante é massa vezes aceleração. Velocidade constante implica aceleração nula e força resultante nula."},
    reflection:"Escolha uma situação cotidiana — bicicleta freando, elevador, objeto caindo ou carro fazendo curva. Desenhe as forças e indique quais hipóteses simplificadoras você utilizaria.",
    references:["OpenStax — University Physics Volume 1: https://openstax.org/details/books/university-physics-volume-1/.","PhET — Forças e movimento: https://phet.colorado.edu/pt_BR/.","Khan Academy — Física: https://pt.khanacademy.org/science/physics."]
  }

];
